<main class="main"><div class="main__inner"><div class="module-page">
<header class="module-page__header"><div><span class="module-eyebrow">Academic governance</span><h1>Academic Configuration</h1><p>Configure sessions, board profiles, attendance thresholds and grading rules without forcing one model on every class.</p></div></header>
<div class="module-grid module-grid--2">
<section class="module-card"><div class="module-card__header"><div><h2>Academic session</h2><p>Use the naming format your institute follows.</p></div></div><form class="module-card__body module-form" method="post" action="<?= url('/admin/settings/academic-profiles/session') ?>"><?= csrf_field() ?><div class="module-field"><label for="session-name">Session name</label><input class="module-input" id="session-name" name="name" placeholder="2026-27" required></div><div class="module-grid module-grid--2"><div class="module-field"><label for="session-start">Starts</label><input class="module-input" id="session-start" type="date" name="start_date" required></div><div class="module-field"><label for="session-end">Ends</label><input class="module-input" id="session-end" type="date" name="end_date" required></div></div><button class="btn btn--primary" type="submit">Save session</button></form></section>
<section class="module-card"><div class="module-card__header"><div><h2>Academic rule profile</h2><p>FBISE defaults are seeded only when FBISE is selected and remain editable.</p></div></div><form class="module-card__body module-form" method="post" action="<?= url('/admin/settings/academic-profiles/profile') ?>"><?= csrf_field() ?><div class="module-grid module-grid--2"><div class="module-field"><label>Name</label><input class="module-input" name="name" placeholder="FBISE SSC 2026" required></div><div class="module-field"><label>Institute / board mode</label><select class="module-select" name="institute_type" required><option value="coaching">Coaching Center</option><option value="internal">Internal School</option><option value="fbise">FBISE</option><option value="provincial_bise">Provincial BISE</option><option value="custom">Custom Board</option></select></div><div class="module-field"><label>Academic session</label><select class="module-select" name="session_id"><option value="">Not session-bound</option><?php foreach($sessions as $s):?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach?></select></div><div class="module-field"><label>Board name</label><input class="module-input" name="board_name" placeholder="Optional"></div><div class="module-field"><label>Minimum attendance %</label><input class="module-input" type="number" min="0" max="100" step="0.01" name="min_attendance" value="75"></div><div class="module-field"><label>Pass threshold %</label><input class="module-input" type="number" min="0" max="100" step="0.01" name="pass_threshold" value="40"></div><div class="module-field"><label>Effective from</label><input class="module-input" type="date" name="effective_from"></div><div class="module-field"><label>Effective to</label><input class="module-input" type="date" name="effective_to"></div></div><div class="module-field"><label>Applicable class levels</label><input class="module-input" name="applicable_levels" placeholder="SSC-I, HSSC-I (optional)"></div><label class="module-check"><input type="checkbox" name="absent_counts_as_zero" value="1"> Count absence as zero during calculation</label><label class="module-check"><input type="checkbox" name="is_default" value="1"> Use as the institute default profile</label><button class="btn btn--primary" type="submit">Create rule profile</button></form></section>
</div>
<section class="module-card"><div class="module-card__header"><div><h2>Configured profiles</h2><p><?= count($profiles) ?> rule profile(s)</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Profile</th><th>Mode</th><th>Session</th><th>Attendance</th><th>Pass mark</th><th>Status</th></tr></thead><tbody><?php if(!$profiles):?><tr><td colspan="6"><div class="compact-empty"><h3>No academic rule profiles</h3><p>Create a profile to make attendance and grading policy session-aware.</p></div></td></tr><?php else:foreach($profiles as $p):?><tr><td><strong><?= e($p['name']) ?></strong><br><small><?= e($p['board_name']?:'Institute-defined') ?></small></td><td><?= e(ucwords(str_replace('_',' ',$p['institute_type']))) ?></td><td><?= e($p['session_name']?:'All sessions') ?></td><td><?= number_format((float)$p['min_attendance'],2) ?>%</td><td><?= number_format((float)$p['pass_threshold'],2) ?>%</td><td><span class="student-status student-status--<?= $p['is_default']?'active':'inactive' ?>"><?= $p['is_default']?'Default':'Available' ?></span></td></tr><?php endforeach;endif?></tbody></table></div></section>
</div></div></main>
